@keyframes heartbeatPulse {
  0% { box-shadow: inset 0 0 50px rgba(220, 20, 60, 0.05); background-color: #050505; }
  50% { box-shadow: inset 0 0 200px rgba(220, 20, 60, 0.25); background-color: #1a0508; }
  100% { box-shadow: inset 0 0 50px rgba(220, 20, 60, 0.05); background-color: #050505; }
}

body {
  animation: heartbeatPulse 4s infinite ease-in-out !important;
  transition: all 0.5s ease;
}
